INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','degree-comparison','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"degree-comparison","title":"Degree: too, enough, so, such and comparison modifiers","level":"B1","order":47,"summary":"Express degree, sufficiency and excess, and make comparisons more precise.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Too means more than wanted","Enough has two positions","So and such","Modify comparisons and adjective strength"],"rules":[{"title":"Too means more than wanted","explanation":"Too + adjective/adverb means an excessive degree for the situation, often followed by a to-infinitive explaining the consequence. It is not simply a stronger version of very. Very hot can be a neutral description; too hot means a limit is exceeded.","pattern":"The soup is **too hot to drink**.","commonMistakes":["Too delicious usually does not mean very delicious unless there is a real problematic excess in context."],"examples":["The instructions let us do the task. “They are **clear enough** to help us prepare the visitor guide.”","The instructions let us do the task. “They are **clear enough** to help us restore the old portrait.”"],"skill":"form"},{"title":"Enough has two positions","explanation":"Enough normally follows an adjective or adverb but precedes a noun. It means the required amount or degree has been reached. A following infinitive can explain the purpose.","pattern":"**clear enough** / **enough time**","commonMistakes":["Enough clear and time enough are not the neutral patterns practised here, though literary placements may differ."],"examples":["“We have **enough time** to prepare the visitor guide before lunch.”","“We have **enough time** to restore the old portrait before lunch.”"],"skill":"meaning"},{"title":"So and such","explanation":"So usually modifies an adjective or adverb. Such modifies a noun phrase, with a/an before a singular count noun. So also combines with much, many, little and few to express quantity.","pattern":"**so useful** / **such a useful guide** / **so many guides**","commonMistakes":["Such useful a guide puts the article in the wrong position for this ordinary pattern."],"examples":["“It is **such a** useful task to prepare the visitor guide.”","“It is **such a** useful task to restore the old portrait.”"],"skill":"contrast"},{"title":"Modify comparisons and adjective strength","explanation":"Much, far and a little can modify a comparative; very does not normally do so directly. Extreme adjectives often take absolutely rather than very. Ordinary adjectives can take very or quite. The acceptable combinations are partly lexical and depend on the adjective’s sense.","pattern":"**much easier** / **a little easier** / **absolutely exhausted**","commonMistakes":["Very easier is not the ordinary comparative pattern. Some adjectives have both gradable and non-gradable senses."],"examples":["Choose the degree modifier that fits: “It is **much** easier to prepare the visitor guide with help.”","Choose the degree modifier that fits: “It is **much** easier to restore the old portrait with help.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-degree","bc-so-such","bc-comparison-modifiers","bc-gradability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"7fb60413-8acb-5de3-ad0e-c088393dba0f","topicSlug":"degree-comparison","level":"B1","prompt":"The instructions let us do the task. “They are ____ to help us prepare the visitor guide.”","choices":[{"id":"A","text":"enough clear"},{"id":"B","text":"clearly enough"},{"id":"C","text":"enough clearly"},{"id":"D","text":"clear enough"}],"answerId":"D","hint":"Enough follows **adjectives**, but precedes **nouns**.","explanation":"Enough follows the adjective: **clear enough**.","keywords":["enough-adjective-order"],"skill":"enough-adjective-order","contextKey":"degree-comparison-1","fingerprint":"81432990140057cd2e4de9411f60cfd2a8aa1311b6611d3120f0ae252d4680d4","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-degree"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Enough follows **adjectives**, but precedes **nouns**.","Enough follows the adjective: **clear enough**.","Choose **clear enough**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Enough normally follows an adjective.","B":"The adjective describes the instructions; clearly is an adverb.","C":"This uses an adverb and reverses its normal relation to enough.","D":"Enough follows the adjective: **clear enough**."}}},{"id":"a140e66a-888f-561f-aabe-23bb6cabfe14","topicSlug":"degree-comparison","level":"B1","prompt":"“We have ____ to prepare the visitor guide before lunch.”","choices":[{"id":"A","text":"time enoughs"},{"id":"B","text":"enough times"},{"id":"C","text":"enoughly time"},{"id":"D","text":"enough time"}],"answerId":"D","hint":"Time here is an **uncountable amount**, so use enough before the noun.","explanation":"Enough precedes the noun: **enough time**.","keywords":["enough-noun-order"],"skill":"enough-noun-order","contextKey":"degree-comparison-1","fingerprint":"96f56197a5605001a9f8752d27bcbd7c22d33f3445da868368b65c19864e4680","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-degree"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Time here is an **uncountable amount**, so use enough before the noun.","Enough precedes the noun: **enough time**.","Choose **enough time**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Enough does not have this plural form.","B":"Times would count occasions rather than the amount of time intended here.","C":"Enoughly is not the standard form.","D":"Enough precedes the noun: **enough time**."}}},{"id":"9b2d140a-e038-5c29-a376-bfcbeb7f597a","topicSlug":"degree-comparison","level":"B1","prompt":"“It is ____ useful task to prepare the visitor guide.”","choices":[{"id":"A","text":"a such"},{"id":"B","text":"such a"},{"id":"C","text":"so a"},{"id":"D","text":"such"}],"answerId":"B","hint":"The modifier introduces a **singular count noun phrase**, not just an adjective.","explanation":"Before singular count task with an adjective, use **such a useful task**.","keywords":["such-noun-phrase"],"skill":"such-noun-phrase","contextKey":"degree-comparison-1","fingerprint":"273a09c7d8b9123a7b70feb29edd4bcdeb9e13326ca76a523e3f5205f609cbf9","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-degree"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The modifier introduces a **singular count noun phrase**, not just an adjective.","Before singular count task with an adjective, use **such a useful task**.","Choose **such a**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The neutral order is such a, not a such.","B":"Before singular count task with an adjective, use **such a useful task**.","C":"So does not take this article + adjective + noun order.","D":"The singular count noun needs the article in this phrase."}}},{"id":"9de8122d-9c43-5abd-a1a8-5c17597f3fe1","topicSlug":"degree-comparison","level":"B1","prompt":"Choose the degree modifier that fits: “It is ____ easier to prepare the visitor guide with help.”","choices":[{"id":"A","text":"much"},{"id":"B","text":"very"},{"id":"C","text":"many"},{"id":"D","text":"such"}],"answerId":"A","hint":"Easier is already **comparative**; choose a modifier that works with comparisons.","explanation":"**Much** can modify comparative easier to show a large difference.","keywords":["comparative-modifier"],"skill":"comparative-modifier","contextKey":"degree-comparison-1","fingerprint":"d7a1b3fc8a1beccbe40ebef57c8996b6a4405bb3cad047065c4e59d20280421d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-degree"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Easier is already **comparative**; choose a modifier that works with comparisons.","**Much** can modify comparative easier to show a large difference.","Choose **much**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Much** can modify comparative easier to show a large difference.","B":"Very does not normally modify a comparative directly.","C":"Many counts plural nouns, not a comparative adjective.","D":"Such normally modifies a noun phrase, not easier by itself."}}},{"id":"0cafe4c9-1095-51aa-a18a-fbbc2eeabbba","topicSlug":"degree-comparison","level":"B1","prompt":"The instructions let us do the task. “They are ____ to help us restore the old portrait.”","choices":[{"id":"A","text":"clearly enough"},{"id":"B","text":"enough clearly"},{"id":"C","text":"clear enough"},{"id":"D","text":"enough clear"}],"answerId":"C","hint":"Enough follows **adjectives**, but precedes **nouns**.","explanation":"Enough follows the adjective: **clear enough**.","keywords":["enough-adjective-order"],"skill":"enough-adjective-order","contextKey":"degree-comparison-2","fingerprint":"e39c7af1468896dfa56d8047202231572617b9a3b2d72139a6dc08442a82b343","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-degree"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Enough follows **adjectives**, but precedes **nouns**.","Eno